import hmac
import hashlib
import base64
import json
import time
import os
import numbers
from typing import Optional, Dict, Any


class KeyStore:
    """Manages signing keys for JWT tokens."""

    def __init__(self):
        self._symmetric_key = os.urandom(32)
        self._rsa_public_key = None
        self._rsa_private_key = None
        self._key_id_map: Dict[str, bytes] = {}
        self._initialize_keys()

    def _initialize_keys(self):
        # In production, these would be loaded from HSM/vault
        self._key_id_map['hmac-primary'] = self._symmetric_key
        self._key_id_map['hmac-backup'] = os.urandom(32)
        # RSA keys would be loaded here for RS256
        # self._rsa_public_key = load_rsa_public_key()

    def get_verification_key(self, key_id: str, algorithm: str) -> Optional[bytes]:
        """Retrieve the appropriate key for verification based on algorithm."""
        if algorithm in ('HS256', 'HS384', 'HS512'):
            return self._key_id_map.get(key_id)
        elif algorithm in ('RS256', 'RS384', 'RS512'):
            # For RSA, return the public key for verification
            return self._rsa_public_key
        elif algorithm == 'none':
            return None
        return None

    def get_signing_key(self, key_id: str) -> bytes:
        return self._key_id_map.get(key_id, self._symmetric_key)


class TokenValidator:
    """Validates JWT tokens with support for multiple algorithms."""

    SUPPORTED_ALGORITHMS = frozenset(['HS256', 'HS384', 'HS512'])
    MAX_TOKEN_SIZE = 8192
    MAX_CLOCK_SKEW = 30  # seconds

    def __init__(self, key_store: KeyStore, required_algorithm: str = 'HS256'):
        self._key_store = key_store
        self._revocation_set: set = set()
        if required_algorithm not in self.SUPPORTED_ALGORITHMS:
            raise ValueError(f"Unsupported required algorithm: {required_algorithm}")
        self._required_algorithm = required_algorithm

    def _b64url_decode(self, data: str) -> bytes:
        """Base64url decode with proper padding."""
        padding = 4 - len(data) % 4
        if padding != 4:
            data += '=' * padding
        return base64.urlsafe_b64decode(data.encode('ascii'))

    def _b64url_encode(self, data: bytes) -> str:
        """Base64url encode without padding."""
        return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

    def _compute_signature(self, algorithm: str, key: bytes, message: bytes) -> bytes:
        """Compute signature using the specified algorithm."""
        if algorithm == 'HS256':
            return hmac.new(key, message, hashlib.sha256).digest()
        elif algorithm == 'HS384':
            return hmac.new(key, message, hashlib.sha384).digest()
        elif algorithm == 'HS512':
            return hmac.new(key, message, hashlib.sha512).digest()
        raise ValueError(f"Unsupported algorithm: {algorithm}")

    def _verify_signature(self, algorithm: str, key: bytes, message: bytes, signature: bytes) -> bool:
        """Verify the token signature."""
        if algorithm.startswith('HS'):
            expected = self._compute_signature(algorithm, key, message)
            return hmac.compare_digest(expected, signature)
        return False

    def _validate_claims(self, payload: Dict[str, Any]) -> Optional[str]:
        """Validate standard JWT claims."""
        now = time.time()

        # Require an expiration claim so tokens cannot live indefinitely.
        if 'exp' not in payload:
            return "Missing expiration"
        if not isinstance(payload['exp'], numbers.Number) or isinstance(payload['exp'], bool):
            return "Invalid expiration claim"
        if now > payload['exp'] + self.MAX_CLOCK_SKEW:
            return "Token expired"

        if 'nbf' in payload:
            if not isinstance(payload['nbf'], numbers.Number) or isinstance(payload['nbf'], bool):
                return "Invalid nbf claim"
            if now < payload['nbf'] - self.MAX_CLOCK_SKEW:
                return "Token not yet valid"

        if 'iss' not in payload:
            return "Missing issuer"

        if payload.get('jti') in self._revocation_set:
            return "Token revoked"

        return None

    def validate_token(self, token: str) -> Dict[str, Any]:
        """Validate a JWT token and return the payload.

        Security: Enforces server-side algorithm choice.
        Rejects 'none' algorithm and any algorithm not matching server config.
        The algorithm from the header is IGNORED for verification — we always
        use self._required_algorithm to prevent algorithm confusion attacks.
        """
        if len(token) > self.MAX_TOKEN_SIZE:
            raise ValueError("Token exceeds maximum size")

        parts = token.split('.')
        if len(parts) != 3:
            raise ValueError("Invalid token format")

        # Decode header
        try:
            header = json.loads(self._b64url_decode(parts[0]))
        except (json.JSONDecodeError, Exception) as e:
            raise ValueError(f"Invalid header: {e}")

        # Extract header algorithm for logging only
        header_algorithm = header.get('alg', '')

        # Security: ENFORCE server-side algorithm regardless of header
        # This prevents algorithm confusion/substitution attacks
        algorithm = self._required_algorithm

        # Security check: reject if header claims 'none'
        if header_algorithm.lower() == 'none':
            raise ValueError("Algorithm 'none' is not permitted")

        # Security check: reject if header algorithm doesn't match expected
        if header_algorithm != self._required_algorithm:
            raise ValueError(f"Algorithm mismatch: expected {self._required_algorithm}, got {header_algorithm}")

        # Get the key ID from header (kid is safe to read from header)
        key_id = header.get('kid', 'hmac-primary')

        # Validate key_id is a known key
        if key_id not in self._key_store._key_id_map:
            raise ValueError(f"Unknown key ID: {key_id}")

        # Retrieve verification key using SERVER-SIDE algorithm choice
        verification_key = self._key_store.get_verification_key(key_id, algorithm)

        if verification_key is None:
            raise ValueError("No verification key available")

        # Decode signature
        signature = self._b64url_decode(parts[2])

        # Construct signing input
        signing_input = f"{parts[0]}.{parts[1]}".encode('ascii')

        # Verify signature using SERVER-SIDE algorithm
        if not self._verify_signature(algorithm, verification_key, signing_input, signature):
            raise ValueError("Invalid signature")

        # Decode and validate payload
        try:
            payload = json.loads(self._b64url_decode(parts[1]))
        except (json.JSONDecodeError, Exception) as e:
            raise ValueError(f"Invalid payload: {e}")

        if not isinstance(payload, dict):
            raise ValueError("Invalid payload structure")

        claim_error = self._validate_claims(payload)
        if claim_error:
            raise ValueError(claim_error)

        return payload

    def revoke_token(self, jti: str) -> None:
        """Add a token ID to the revocation set."""
        self._revocation_set.add(jti)


class AuthMiddleware:
    """HTTP middleware for JWT authentication."""

    def __init__(self):
        self._key_store = KeyStore()
        self._validator = TokenValidator(self._key_store, required_algorithm='HS256')

    def authenticate(self, authorization_header: str) -> Dict[str, Any]:
        """Authenticate a request using the Authorization header."""
        if not authorization_header:
            raise PermissionError("Missing authorization header")

        parts = authorization_header.split(' ', 1)
        if len(parts) != 2 or parts[0].lower() != 'bearer':
            raise PermissionError("Invalid authorization format")

        token = parts[1].strip()

        try:
            payload = self._validator.validate_token(token)
        except ValueError as e:
            raise PermissionError(f"Authentication failed: {e}")

        return {
            'user_id': payload.get('sub'),
            'roles': payload.get('roles', []),
            'issuer': payload.get('iss'),
            'token_id': payload.get('jti')
        }
